import {STATUSES,count,available,watch,undo,minutes,validateBackup} from './model.js';

const icons={moon:'<path d="M20.7 13A9 9 0 0 1 11 3.3 9 9 0 1 0 20.7 13Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',list:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 8 1 1 2-2m2 1h3M8 14h2m3 0h3m-8 3h8"/>',history:'<path d="M3 11a9 9 0 1 1 2.6 7M3 4v7h7m2-4v5l3 2"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',play:'<path d="m9 5 11 7-11 7Z"/>',check:'<path d="m5 12 4 4L19 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-10 4h2"/>',plus:'<path d="M12 5v14M5 12h14"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',cloud:'<path d="M7 18a5 5 0 1 1 0-10 6 6 0 0 1 11 1 4.5 4.5 0 0 1 0 9M9 15l3 3 3-3m-3 3v-7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',film:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 3v18M17 3v18M3 8h4m-4 8h4M17 8h4m-4 8h4"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.film}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=url=>{try{const u=new URL(url,location.href);return ['http:','https:'].includes(u.protocol)?esc(u.href):'';}catch{return '';}};
const $=s=>document.querySelector(s);
const KEY='yoru-library-v1';
let catalog=[],state,view='dashboard',filter='all',kind='all',sort='recent',query='',searchResults=[],searchBusy=false,searchNotice='',searchToken=0,menuOpen=false;
let persistenceBroken=false;
const getTitle=id=>catalog.find(t=>t.id===id);
const watched=id=>count(state,id);
const fmtTime=n=>`${Math.floor(n/60)} ч${n%60?' '+Math.round(n%60)+' мин':''}`;
const num=n=>new Intl.NumberFormat('ru-RU').format(n);
const dayKey=at=>new Date(at).toLocaleDateString('sv-SE');
const today=()=>dayKey(Date.now());
function save(){try{localStorage.setItem(KEY,JSON.stringify({state,catalog}));}catch{persistenceBroken=true;toast('Не удалось сохранить данные. Экспортируйте резервную копию в профиле.');}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function demoState(){
 const s={name:'Акира',demo:true,demoVersion:2,entries:{},events:[],createdAt:new Date().toISOString()};
 const setup=[['anime-52991',12,'watching'],['tv-44933',5,'watching'],['anime-40748',8,'watching'],['anime-44511',3,'watching'],['anime-1535',37,'completed'],['anime-5114',64,'completed'],['anime-16498',0,'planned'],['anime-38000',4,'paused'],['anime-21',3,'dropped'],['tv-2993',0,'planned']];
 for(const [id,n,status] of setup){const t=getTitle(id);if(!t)continue;s.entries[id]={status,updatedAt:Date.now()-setup.findIndex(a=>a[0]===id)*1000};for(let i=0;i<n;i++){const date=new Date();date.setDate(date.getDate()-Math.floor((n-1-i)/2));date.setHours(19+(i%3),15,0,0);if(date>Date.now())date.setDate(date.getDate()-1);s.events.push({id:crypto.randomUUID(),titleId:id,episode:i+1,minutes:t.episodeData?.[i]?.duration||t.duration,at:date.toISOString()});}}
 s.events.sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));return s;
}
function entries(status){return Object.entries(state.entries).filter(([id,e])=>getTitle(id)&&(!status||e.status===status));}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action||`<span class="date">${icon('calendar')}${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}</span>`}</div>`;}
function navItem(route,label,i){return `<a class="nav-item ${view===route?'active':''}" href="#/${route}" ${view===route?'aria-current="page"':''}>${icon(i)}${label}${route==='library'?`<span class="nav-number">${entries().length}</span>`:''}</a>`;}
function render(){
 const route=location.hash.slice(2).split('/');view=route[0]||'dashboard';if(!['dashboard','library','history','stats','search','title'].includes(view))view='dashboard';
 if(view==='library')filter=Object.hasOwn(STATUSES,route[1])?route[1]:'all';
 const labels={dashboard:'Обзор',library:'Мой список',history:'История просмотров',stats:'Статистика',search:'Поиск',title:'Тайтл'};
 document.title=`${view==='title'?getTitle(route[1])?.title||'Тайтл':labels[view]} — Yoru`;
 $('#app').innerHTML=`<div class="shell"><div class="mobile-shade ${menuOpen?'open':''}" data-action="menu"></div><aside class="sidebar ${menuOpen?'open':''}"><a class="logo" href="#/dashboard">${icon('moon')}yoru<small>夜</small></a><div class="brand-note">Твоя история в эпизодах</div><p class="nav-label">ЛИЧНОЕ ПРОСТРАНСТВО</p><nav aria-label="Главная навигация">${navItem('dashboard','Обзор','grid')}${navItem('library','Мой список','list')}${navItem('history','История','history')}${navItem('stats','Статистика','chart')}${navItem('search','Найти тайтл','search')}</nav><div class="divider"></div><p class="nav-label">МОЯ КОЛЛЕКЦИЯ</p>${Object.entries(STATUSES).map(([s,label])=>`<a class="status-link" href="#/library/${s}"><i class="dot ${s}"></i>${label}<span>${entries(s).length}</span></a>`).join('')}<div class="sidebar-bottom"><span class="storage-note">${icon('cloud')}${persistenceBroken?'Не удалось сохранить':'Хранится в этом браузере'}</span><button class="profile-btn" data-action="profile"><span class="avatar">${esc(state.name[0]?.toUpperCase()||'Я')}</span><span><strong>${esc(state.name)}</strong><small>${state.demo?'Демо-профиль':'Личное пространство'}</small></span>${icon('settings')}</button></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="breadcrumb">Моё пространство ${icon('chevron')}<span>${labels[view]}</span></div><div class="top-tools"><form class="searchbox" id="global-search">${icon('search')}<input aria-label="Поиск аниме и сериалов" name="q" placeholder="Найти аниме или сериал…" autocomplete="off"><span class="key">Ctrl K</span></form><button class="avatar top-avatar" data-action="profile" aria-label="Настройки профиля">${esc(state.name[0]?.toUpperCase()||'Я')}</button></div></header><main class="content" id="main">${state.demo?`<div class="demo-banner"><span>Вы в демо-профиле. Попробуйте отметить серию — всё уже работает.</span><button data-action="start">Создать свой список ${icon('arrow')}</button></div>`:''}${view==='dashboard'?dashboard():view==='library'?library():view==='history'?history():view==='stats'?stats():view==='search'?searchPage():detail(route[1])}<footer class="footer"><span>yoru · Каждая история остаётся с тобой.</span><span>Каталоги: <a href="https://shikimori.io" target="_blank" rel="noreferrer">Shikimori</a> · <a href="https://www.tvmaze.com" target="_blank" rel="noreferrer">TVmaze</a> <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA</a></span></footer></main></div></div>`;
 if(view==='search')$('#search-input').value=query;
 if(view==='title'){const t=getTitle(route[1]);if(t?.needsDetails)loadDetails(t);}
}
function statsCards(){const m=minutes(state),week=Date.now()-7*864e5;return `<div class="stats">${[
 ['clock','Время за просмотром',`${Math.floor(m/60)} <small>ч</small> ${Math.round(m%60)} <small>мин</small>`,`<span class="green">${fmtTime(state.events.filter(e=>Date.parse(e.at)>week).reduce((s,e)=>s+e.minutes,0))}</span> за последние 7 дней`],
 ['play','Просмотрено эпизодов',num(state.events.length),'Одна серия — ещё одна история'],
 ['check','Завершено тайтлов',num(entries('completed').length),'Истории, которые остались с вами'],
 ['list','В вашей коллекции',num(entries().length),`${entries('watching').length} смотрю · ${entries('planned').length} в планах`]
 ].map(([i,l,v,c])=>`<div class="stat"><div class="stat-top">${l}${icon(i)}</div><div class="stat-value">${v}</div><div class="stat-caption">${c}</div></div>`).join('')}</div>`;}
function continueCard(t){const n=watched(t.id),total=t.total||available(t),limit=available(t);return `<article class="continue-card"><a class="card-visual" href="#/title/${esc(t.id)}"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt="${esc(t.title)}" loading="lazy"><span class="kind-tag">${t.kind==='anime'?'АНИМЕ':'СЕРИАЛ'} · ${t.year||'—'}</span></a><div class="card-body"><a class="title-link" href="#/title/${esc(t.id)}" title="${esc(t.title)}">${esc(t.title)}</a><div class="subtitle">${esc(t.original)}</div><div class="progress-label"><span>Эпизод ${n} <span>/ ${total||'?'}</span></span><b>${total?Math.round(n/total*100)+'%':'В процессе'}</b></div><div class="progress-track"><span style="width:${total?Math.min(n/total*100,100):0}%"></span></div><div class="card-bottom"><span>${limit!==null&&n>=limit?'Вы всё посмотрели':`Далее · эпизод ${n+1}`}</span><button class="add-episode" data-action="watch" data-id="${esc(t.id)}" ${limit!==null&&n>=limit?'disabled':''} aria-label="Отметить следующую серию: ${esc(t.title)}">+1 серия</button></div></div></article>`;}
function posterCard(t,progress=false){return `<article class="poster-card"><a class="poster" href="#/title/${esc(t.id)}"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt="Постер: ${esc(t.title)}" loading="lazy">${t.score?`<span class="score">${icon('star')}${Number(t.score).toFixed(1)}</span>`:''}</a><a class="title-link" href="#/title/${esc(t.id)}" title="${esc(t.title)}">${esc(t.title)}</a><div class="poster-meta">${progress?`<i class="dot ${state.entries[t.id].status}"></i>${esc(STATUSES[state.entries[t.id].status])}`:`${t.year||'—'}<i></i>${t.kind==='anime'?'Аниме':'Сериал'}`}</div>${progress?`<div class="progress-label"><span>${watched(t.id)} / ${t.total||available(t)||'?'} эп.</span><span>${fmtTime(state.events.filter(e=>e.titleId===t.id).reduce((s,e)=>s+e.minutes,0))}</span></div><div class="progress-track"><span style="width:${Math.min(100,watched(t.id)/(t.total||available(t)||Infinity)*100)}%"></span></div>`:''}</article>`;}
function section(title,i,content,href,label='Все тайтлы'){return `<div class="section-head"><div class="section-title">${icon(i)}<h2>${title}</h2></div><a class="text-link" href="${href}">${label}${icon('arrow')}</a></div>${content}`;}
function empty(title,text,link='#/search',label='Найти тайтл'){return `<div class="empty">${icon('moon')}<h3>${title}</h3><p>${text}</p><a class="btn" href="${link}">${icon('search')}${label}</a></div>`;}
function dashboard(){const watching=entries('watching').sort((a,b)=>b[1].updatedAt-a[1].updatedAt).slice(0,4).map(([id])=>getTitle(id));const picks=catalog.filter(t=>!state.entries[t.id]||['planned','paused'].includes(state.entries[t.id].status)).slice(0,6);return `${heading(`Хорошего просмотра, ${esc(state.name)} <span style="color:#b6a0ff">✦</span>`,'Все ваши миры. В одном месте.')}<section class="hero"><div class="hero-art" aria-hidden="true"></div><div class="hero-text"><span class="eyebrow">ВАШ ЛИЧНЫЙ WATCHLIST</span><h2>Ещё одна серия —<br>ещё одна история.</h2><p>Сохраняйте то, что любите.<br>А мы поможем не потерять ни одного эпизода.</p><a class="btn" href="#/search">${icon('plus')}Найти новую историю</a></div></section>${statsCards()}${section('Продолжить просмотр','play',watching.length?`<div class="continue-grid">${watching.map(continueCard).join('')}</div>`:empty('Здесь начнётся ваша история','Найдите аниме или сериал, выберите «Смотрю» и отмечайте просмотренные серии.'),'#/library/watching','Мой список')}${section('Следующая история','spark',`<div class="discovery">${picks.map(t=>posterCard(t)).join('')}</div>`,'#/search','Открыть каталог')}`;}
function library(){let list=entries(filter==='all'?null:filter).map(([id])=>getTitle(id)).filter(t=>kind==='all'||t.kind===kind);list.sort((a,b)=>sort==='name'?a.title.localeCompare(b.title,'ru'):sort==='progress'?watched(b.id)-watched(a.id):state.entries[b.id].updatedAt-state.entries[a.id].updatedAt);return `${heading('Мой список','Большие миры и маленькие планы.',`<a class="btn" href="#/search">${icon('plus')}Добавить тайтл</a>`)}<div class="tabs" role="tablist" aria-label="Статус просмотра">${[['all','Все'],...Object.entries(STATUSES)].map(([s,label])=>`<button role="tab" aria-selected="${filter===s}" class="tab ${filter===s?'active':''}" data-action="filter" data-value="${s}">${label}<span>${s==='all'?entries().length:entries(s).length}</span></button>`).join('')}</div><div class="toolbar">${kindFilters()}<select class="select" id="sort-select" aria-label="Сортировка">${[['recent','Недавно добавленные'],['name','По названию'],['progress','По прогрессу']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></div>${list.length?`<div class="library-grid">${list.map(t=>posterCard(t,true)).join('')}</div>`:empty('Пока ни одного тайтла','В этом списке ещё нет историй. Самое время найти что-нибудь интересное.')}`;}
function kindFilters(){return `<div class="segmented" aria-label="Тип тайтла">${[['all','Все'],['anime','Аниме'],['tv','Сериалы']].map(([v,l])=>`<button class="segment ${kind===v?'active':''}" data-action="kind" data-value="${v}" aria-pressed="${kind===v}">${l}</button>`).join('')}</div>`;}
function history(){const events=[...state.events].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));const groups=Map.groupBy?Map.groupBy(events,e=>dayKey(e.at)):events.reduce((map,e)=>{const d=dayKey(e.at);map.set(d,[...(map.get(d)||[]),e]);return map;},new Map());return `${heading('История просмотров','Моменты, из которых складываются ваши истории.')}<div class="toolbar"><span class="filter-label">${num(events.length)} эпизодов · ${fmtTime(minutes(state))}</span><button class="btn ghost" data-action="export">${icon('download')}Экспорт данных</button></div>${events.length?[...groups].map(([day,es])=>`<section class="history-group"><h2 class="history-date">${day===today()?'Сегодня':new Date(day+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}<span style="float:right">${fmtTime(es.reduce((n,e)=>n+e.minutes,0))}</span></h2>${es.map(e=>{const t=getTitle(e.titleId);return `<a class="history-row" href="#/title/${esc(t.id)}"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt="" loading="lazy"><div class="info"><strong>${esc(t.title)}</strong><small>Эпизод ${e.episode}${t.episodeData?.[e.episode-1]?.label?' · '+esc(t.episodeData[e.episode-1].label):''}</small></div><time>${new Date(e.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time><span class="history-min">+ ${e.minutes} мин</span>${icon('check')}</a>`;}).join('')}</section>`).join(''):empty('Всё только начинается','Отметьте первую просмотренную серию. Здесь появятся дата, эпизод и время просмотра.')}`;}
function stats(){const days=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);return {key:dayKey(date),label:date.toLocaleDateString('ru-RU',{weekday:'short'}),minutes:state.events.filter(e=>dayKey(e.at)===dayKey(date)).reduce((s,e)=>s+e.minutes,0)};});const max=Math.max(...days.map(d=>d.minutes),60);return `${heading('Ваша статистика','Время, проведённое в любимых мирах.')}${statsCards()}<section class="chart-box"><div class="section-head"><h2>Последние 7 дней</h2><span class="filter-label">Минуты просмотра</span></div><div class="chart" role="img" aria-label="Время просмотра за неделю: ${days.map(d=>d.label+' '+d.minutes+' минут').join(', ')}">${days.map(d=>`<div class="chart-col"><small>${d.minutes||'—'}</small><div class="chart-bar" style="height:${d.minutes/max*85}%"></div><span>${d.label}</span></div>`).join('')}</div></section><div class="type-stats">${[['anime','Аниме','spark'],['tv','Сериалы','film']].map(([k,l,i])=>{const ev=state.events.filter(e=>getTitle(e.titleId)?.kind===k);return `<div class="type-stat"><span class="section-title">${icon(i)}${l}</span><strong>${fmtTime(ev.reduce((s,e)=>s+e.minutes,0))}</strong><p>${ev.length} эпизодов · ${entries().filter(([id])=>getTitle(id).kind===k).length} тайтлов в коллекции</p></div>`;}).join('')}</div>`;}
function localSearch(q){const norm=s=>s.toLocaleLowerCase('ru').replace(/ё/g,'е');return catalog.filter(t=>[t.title,t.original,...(t.aliases||[])].filter(Boolean).some(s=>norm(s).includes(norm(q))));}
function searchPage(){const list=(query?searchResults:catalog).filter(t=>kind==='all'||t.kind===kind);return `${heading('Найти свою историю','Что будете смотреть дальше?')}<form class="search-large" id="catalog-search">${icon('search')}<input id="search-input" name="q" aria-label="Название тайтла" placeholder="Название аниме или сериала…" autocomplete="off"><button class="btn" type="submit">Найти ${icon('arrow')}</button></form><div class="toolbar">${kindFilters()}<button class="text-link" data-action="manual">${icon('plus')}Добавить вручную</button></div><p class="search-note">${searchBusy?'<span class="loading">Ищем в каталогах…</span>':query?`По запросу «${esc(query)}» · найдено ${list.length}`:'Подборка для вашего следующего вечера. Введите название, чтобы искать в каталогах Shikimori и TVmaze.'}${searchNotice?`<br>${esc(searchNotice)}`:''}</p>${list.length?`<div class="library-grid">${list.map(t=>posterCard(t)).join('')}</div>`:searchBusy?'<div class="empty"><div class="loading">Ищем вашу следующую историю…</div></div>':empty('Пока ничего не нашлось','Попробуйте оригинальное или английское название. Если тайтла нет в каталоге, его можно добавить вручную.','#/search','Изменить запрос')}`;}
function detail(id){const t=getTitle(id);if(!t)return empty('Тайтл не найден','Вернитесь к поиску и выберите нужный результат.');const n=watched(id),released=available(t),status=state.entries[id]?.status,limit=released;return `<a href="#/library" class="detail-back">${icon('back')}К моему списку</a><section class="detail-hero"><div class="detail-poster"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt="${esc(t.title)}"></div><div class="detail-main"><div class="detail-title"><span class="eyebrow">${t.kind==='anime'?'АНИМЕ':'СЕРИАЛ'} · ${t.year||'—'}${t.score?' · ★ '+t.score:''}</span><h1>${esc(t.title)}</h1><div class="detail-original">${esc(t.original)}</div><div class="tags">${(t.genres||[]).slice(0,4).map(g=>`<span class="tag">${esc(genreRu[g]||g)}</span>`).join('')}<span class="tag">${t.airing?'Продолжается':'Завершён'}</span></div></div><div class="detail-info"><div><span>Вышло эпизодов</span><b>${t.needsDetails?'Загрузка…':released===null?'Нет данных':released}</b></div><div><span>Всего эпизодов</span><b>${t.total||'Не объявлено'}</b></div><div><span>Один эпизод</span><b>${t.duration?t.duration+' мин':'Не указано'}</b></div></div><p class="synopsis">${esc(ruDescriptions[t.id]||t.description||'У этой истории пока нет описания. Добавьте её в список и начните просмотр.')}</p><div class="detail-actions"><select class="select" id="title-status" data-id="${esc(id)}" aria-label="Статус просмотра"><option value="" ${!status?'selected':''}>Добавить в список…</option>${Object.entries(STATUSES).map(([s,l])=>`<option value="${s}" ${status===s?'selected':''}>${l}</option>`).join('')}</select>${t.apiId?`<button class="btn ghost" data-action="refresh" data-id="${esc(id)}">Обновить данные</button>`:`<button class="btn ghost" data-action="edit-manual" data-id="${esc(id)}">Редактировать</button>`}${!t.duration?`<button class="btn secondary" data-action="duration" data-id="${esc(id)}">Указать длительность</button>`:''}</div>${t.source?`<a class="source-link" href="${safeUrl(t.source)}" target="_blank" rel="noreferrer">Информация: ${t.kind==='anime'?'Shikimori':'TVmaze'} ↗</a>`:''}</div></section><section class="tracking-panel"><div class="tracking-top"><div><h2>Ваш прогресс</h2><p>${status?STATUSES[status]:'Добавьте тайтл или отметьте первую серию'}</p></div><div class="tracking-count">${n} <small>/ ${t.total||released||'?'} эп.</small></div></div><div class="progress-track"><span style="width:${Math.min(n/(t.total||released||Infinity)*100,100)}%"></span></div><div class="tracking-controls"><button class="btn" data-action="watch" data-id="${esc(id)}" ${t.needsDetails||(limit!==null&&n>=limit)||!t.duration?'disabled':''}>${icon('plus')}${limit!==null&&n>=limit?'Все вышедшие серии отмечены':'Посмотрел серию '+(n+1)}${t.duration&&!(limit!==null&&n>=limit)?' · '+(t.episodeData?.[n]?.duration||t.duration)+' мин':''}</button><button class="btn ghost" data-action="undo" data-id="${esc(id)}" ${!n?'disabled':''}>${icon('back')}Отменить последнюю</button></div><div class="tracking-note">${fmtTime(state.events.filter(e=>e.titleId===id).reduce((s,e)=>s+e.minutes,0))} за просмотром этого тайтла. Каждая отметка добавляет эпизод и его длительность в историю.${released===null?' Число вышедших серий неизвестно: прогресс отмечается вручную.':''}${t.detailError?' Не удалось обновить сведения об эпизодах. Попробуйте открыть карточку позже.':''}</div>${(t.total||released||n)?`<div class="episode-grid" aria-label="Просмотренные эпизоды">${Array.from({length:Math.min(t.total||released||n+1,120)},(_,i)=>`<button class="ep ${i<n?'seen':i===n?'next':''}" ${i===n&&!t.needsDetails&&(limit===null||i<limit)?`data-action="watch" data-id="${esc(id)}" aria-label="Отметить эпизод ${i+1}"`:'disabled'} title="Эпизод ${i+1}${i<n?' просмотрен':''}">${i<n?'✓':i+1}</button>`).join('')}</div>`:''}</section>`;}
const genreRu={Action:'Экшен',Adventure:'Приключения',Drama:'Драма',Fantasy:'Фэнтези',Comedy:'Комедия',Mystery:'Мистика',Thriller:'Триллер',Romance:'Романтика',Supernatural:'Сверхъестественное',Horror:'Ужасы',Suspense:'Саспенс','Sci-Fi':'Фантастика',ScienceFiction:'Фантастика','Science-Fiction':'Фантастика'};
const ruDescriptions={'anime-52991':'После победы над королём демонов эльфийская волшебница Фрирен отправляется в новое путешествие. Спустя десятилетия она начинает понимать, что значили для неё люди, с которыми она когда-то спасла мир. Тихая история о времени, памяти и умении быть рядом.','anime-44511':'Дэндзи мечтает о простой жизни: еде, крыше над головой и ком-то рядом. Но договор с демоном-бензопилой меняет всё — теперь он охотник на демонов в мире, где любая мечта имеет свою цену.','anime-40748':'Обычный школьник Юдзи Итадори оказывается в мире проклятий и магов. Вместе с новыми друзьями он учится управлять силой, которая одновременно даёт шанс спасти других и угрожает ему самому.','anime-16498':'За огромными стенами человечество скрывается от титанов. Когда привычный мир рушится, Эрен и его друзья вступают в борьбу за свободу — и постепенно узнают, насколько велика цена правды.','tv-44933':'Сотрудники корпорации Lumon добровольно проходят процедуру, разделяющую воспоминания о работе и личной жизни. Но идеальный баланс начинает трещать по швам, когда одна из личностей решает узнать, что находится по другую сторону лифта.'};
async function fetchJson(url){const response=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('Каталог временно недоступен');return response.json();}
function animeFrom(a){return {id:'anime-'+a.id,apiId:a.id,provider:'shikimori',kind:'anime',title:a.russian||a.name,original:(a.english||[]).find(Boolean)||a.name,aliases:[a.name,...(a.english||[]),...(a.synonyms||[])].filter(Boolean),poster:a.image?.original?'https://shikimori.io'+a.image.original:null,total:a.episodes||null,released:a.status==='released'?a.episodes||null:a.episodes_aired??null,duration:a.duration||null,year:a.aired_on?.slice(0,4),score:Number(a.score)||null,genres:(a.genres||[]).map(g=>g.russian||g.name),description:(a.description||'').replace(/\[\/?[^\]]+\]/g,''),airing:a.status!=='released',source:'https://shikimori.io'+a.url,needsDetails:!a.duration};}
function tvFrom(a){return {id:'tv-'+a.id,apiId:a.id,kind:'tv',title:a.name,original:a.name,aliases:[],poster:a.image?.original||a.image?.medium,total:null,released:null,duration:a.averageRuntime||a.runtime||null,year:a.premiered?.slice(0,4),score:a.rating?.average,genres:a.genres||[],description:(a.summary||'').replace(/<[^>]+>/g,''),airing:a.status!=='Ended',source:a.url,needsDetails:true};}
async function search(q){query=q.trim();searchToken++;const token=searchToken;if(!query){searchResults=[];searchNotice='';searchBusy=false;render();return;}searchResults=localSearch(query);searchBusy=true;searchNotice='';render();const alias=searchResults.find(t=>t.title.toLowerCase()===query.toLowerCase())?.original;const requestQ=alias||query;const jobs=[['anime',`https://shikimori.io/api/animes?search=${encodeURIComponent(query)}&limit=12&censored=true`],['tv',`https://api.tvmaze.com/search/shows?q=${encodeURIComponent(requestQ)}`]].filter(([k])=>kind==='all'||kind===k);const results=await Promise.allSettled(jobs.map(async([k,url])=>{const r=await fetchJson(url);return k==='anime'?r.map(animeFrom):r.map(x=>tvFrom(x.show));}));if(token!==searchToken)return;const found=new Map(searchResults.map(t=>[t.id,t]));let failures=0;for(const result of results){if(result.status==='rejected'){failures++;continue;}for(const t of result.value){const existing=getTitle(t.id);if(existing){found.set(t.id,existing);}else{catalog.push(t);found.set(t.id,t);}}}searchResults=[...found.values()];searchBusy=false;searchNotice=failures?'Один из каталогов недоступен. Показаны доступные результаты и сохранённые тайтлы. При необходимости добавьте тайтл вручную.':'Поиск по внешним каталогам лучше работает с оригинальным или английским названием.';save();if(view==='search')render();}
const loadingDetails=new Set();async function loadDetails(t){if(loadingDetails.has(t.id))return;loadingDetails.add(t.id);try{if(t.kind==='tv'){const eps=await fetchJson(`https://api.tvmaze.com/shows/${t.apiId}/episodes`);t.episodeData=eps.map(e=>({duration:e.runtime||t.duration||null,airdate:e.airstamp,label:`S${String(e.season).padStart(2,'0')}E${String(e.number||0).padStart(2,'0')}`}));t.released=available(t);t.total=t.airing?null:eps.length;}else{const a=await fetchJson(`https://shikimori.io/api/animes/${t.apiId}`);const updated=animeFrom(a);Object.assign(t,updated,{poster:t.poster?.startsWith('assets/')?t.poster:updated.poster});}t.needsDetails=false;t.detailError=false;save();}catch{t.detailError=true;}finally{loadingDetails.delete(t.id);if(view==='title'&&location.hash.endsWith('/'+t.id)){if(t.detailError)t.needsDetails=false;render();}}}
function dialog(content){$('#profile-dialog').innerHTML=content;$('#profile-dialog').showModal();}
function dialogHead(title){return `<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>`;}
function profile(){dialog(`${dialogHead('Ваше пространство')}<form id="profile-form"><label class="field">Как вас называть?<input name="name" value="${esc(state.name)}" maxlength="35" required></label><button class="btn" type="submit">Сохранить</button></form><div class="separator"></div><p class="dialog-help">Данные сохраняются в этом браузере. Для переноса на другое устройство скачайте резервную копию и импортируйте её там.</p><div class="profile-actions"><button class="btn secondary" data-action="export">${icon('download')}Экспорт</button><label class="btn secondary" style="cursor:pointer">Импорт<input type="file" id="import-file" accept="application/json,.json" hidden></label></div>${state.demo?'<div class="separator"></div><button class="btn" data-action="start">Начать свою коллекцию</button>':''}`);}
function start(){if($('#profile-dialog').open)$('#profile-dialog').close();dialog(`${dialogHead('Начнём вашу историю')}<p class="dialog-help">Демо-коллекция уступит место вашему личному списку. Найдите первый тайтл и добавьте его в планы или начните смотреть.</p><form id="start-form"><label class="field">Как вас называть?<input name="name" placeholder="Ваше имя" maxlength="35" required autofocus></label><button class="btn" type="submit">Создать мой список ${icon('arrow')}</button></form>`);}
function manual(t=null){dialog(`${dialogHead(t?'Редактировать тайтл':'Добавить свой тайтл')}<form id="manual-form" ${t?`data-id="${esc(t.id)}"`:''}><label class="field">Название<input name="title" required maxlength="150" value="${esc(t?.title||query)}"></label><label class="field">Тип<select name="kind"><option value="anime" ${t?.kind==='anime'?'selected':''}>Аниме</option><option value="tv" ${t?.kind==='tv'?'selected':''}>Сериал</option></select></label><label class="field">Всего эпизодов (если известно)<input name="total" type="number" min="1" max="100000" value="${t?.total||''}" placeholder="Не объявлено"></label><label class="field">Сколько уже вышло<input name="released" type="number" min="0" max="100000" value="${t?.released??''}" required></label><label class="field">Длительность одного эпизода, минут<input name="duration" type="number" min="1" max="1440" required value="${t?.duration||24}"></label><button class="btn" type="submit">${t?'Сохранить':'Добавить в планы'}</button></form>`);}
function exportData(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),state,catalog},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`yoru-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия скачана');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id,value}=b.dataset;if(action==='watch'){const t=getTitle(id);if(!t)return;const result=watch(state,t);if(result.ok){save();render();toast(`Эпизод ${result.event.episode} отмечен · +${result.event.minutes} мин`);}else toast(result.reason);}else if(action==='undo'){undo(state,id);save();render();toast('Последняя отметка отменена, время пересчитано');}else if(action==='filter'){filter=value;location.hash='#/library'+(value==='all'?'':'/'+value);render();}else if(action==='kind'){kind=value;render();if(view==='search'&&query)search(query);}else if(action==='profile')profile();else if(action==='start')start();else if(action==='close-dialog')$('#profile-dialog').close();else if(action==='export')exportData();else if(action==='manual')manual();else if(action==='edit-manual')manual(getTitle(id));else if(action==='refresh'){const t=getTitle(id);t.needsDetails=true;t.detailError=false;render();}else if(action==='menu'){menuOpen=!menuOpen;render();}else if(action==='duration'){dialog(`${dialogHead('Длительность эпизода')}<form id="duration-form" data-id="${esc(id)}"><label class="field">Минуты<input type="number" name="duration" min="1" max="1440" required></label><button class="btn" type="submit">Сохранить</button></form>`);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const data=new FormData(f);if(f.id==='global-search'||f.id==='catalog-search'){const q=String(data.get('q')||'');location.hash='#/search';search(q);}else if(f.id==='profile-form'){state.name=String(data.get('name')).trim()||'Зритель';save();$('#profile-dialog').close();render();toast('Профиль сохранён');}else if(f.id==='start-form'){state={name:String(data.get('name')).trim()||'Зритель',demo:false,entries:{},events:[],createdAt:new Date().toISOString()};filter='all';save();$('#profile-dialog').close();location.hash='#/dashboard';render();}else if(f.id==='manual-form'){const total=Number(data.get('total'))||null,released=Number(data.get('released'));if(total!==null&&released>total){toast('Вышедших серий не может быть больше общего числа');return;}const existing=getTitle(f.dataset.id);if(released<watched(existing?.id)){toast('Число вышедших серий меньше вашего прогресса');return;}const t={id:existing?.id||'custom-'+crypto.randomUUID(),kind:data.get('kind'),title:String(data.get('title')).trim(),original:'Добавлено вами',total,released,duration:Number(data.get('duration')),genres:[],description:'',airing:total===null||released<total};if(!t.title)return;if(existing)Object.assign(existing,t);else{catalog.push(t);state.entries[t.id]={status:'planned',updatedAt:Date.now()};}save();$('#profile-dialog').close();location.hash='#/title/'+t.id;render();}else if(f.id==='duration-form'){getTitle(f.dataset.id).duration=Number(data.get('duration'));save();$('#profile-dialog').close();render();}});
document.addEventListener('change',async e=>{if(e.target.id==='title-status'){const id=e.target.dataset.id,status=e.target.value;if(!status)return;state.entries[id]={...state.entries[id],status,updatedAt:Date.now()};save();render();toast('Статус изменён. Серии отмечаются отдельно.');}else if(e.target.id==='sort-select'){sort=e.target.value;render();}else if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>15e6)throw Error('Файл слишком большой');const data=validateBackup(JSON.parse(await file.text()));dialog(`${dialogHead('Восстановить коллекцию?')}<p class="dialog-help">Профиль «${esc(data.state.name)}»: ${Object.keys(data.state.entries).length} тайтлов, ${data.state.events.length} эпизодов. Импорт заменит текущую коллекцию. Сначала можно экспортировать её резервную копию.</p><div class="profile-actions"><button class="btn secondary" data-action="export">Экспорт текущей</button><button class="btn" id="confirm-import">Восстановить</button></div>`);$('#confirm-import').onclick=()=>{state=data.state;catalog=data.catalog;save();$('#profile-dialog').close();location.hash='#/dashboard';render();toast('Коллекция восстановлена');};}catch(err){toast(err.message||'Не удалось прочитать файл');}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search input').focus();}});
window.addEventListener('hashchange',()=>{menuOpen=false;render();window.scrollTo({top:0});});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const data=JSON.parse(e.newValue);state=data.state;catalog=data.catalog;render();}catch{}}});
try{catalog=await fetchJson('./catalog.json');let stored;try{stored=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}if(stored?.state&&Array.isArray(stored.catalog)){state=stored.state;catalog=[...stored.catalog,...catalog.filter(t=>!stored.catalog.some(s=>s.id===t.id))];}else{state=demoState();save();}if(state.demo&&state.demoVersion!==2){state=demoState();save();}render();}catch{$('#app').innerHTML='<div class="boot">yoru<span>Не удалось загрузить каталог. Обновите страницу.</span></div>';}
